package com.orcaphone.core

import com.orcaphone.core.config.BuiltinProfiles
import com.orcaphone.core.gcode.Thumbnail
import com.orcaphone.core.math.Mat4
import com.orcaphone.core.mesh.Primitives
import com.orcaphone.core.slice.Slicer
import java.io.ByteArrayInputStream
import java.io.File
import java.util.Base64
import javax.imageio.ImageIO
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * The G-code carries what Moonraker (Mainsail/Fluidd) reads: the PrusaSlicer-style "generated by" line it
 * identifies slicers by, the estimated time and filament use, and PNG thumbnails. The patterns below are
 * the ones Moonraker's metadata.py uses.
 */
class GCodeMetadataTest {
    private fun sliceSample(): String {
        val printer = BuiltinProfiles.printers.first()
        val process = BuiltinProfiles.processes.first { it.id == "builtin-0.20" }
        val mesh = Primitives.cylinder(15.0, 20.0).transformed(Mat4.translation(printer.bedWidth / 2, printer.bedDepth / 2, 0.0))
        val dir = System.getenv("GCODE_OUT")?.let { File(it).apply { mkdirs() } }
        val out = if (dir != null) File(dir, "orcaphone_sample.gcode") else File.createTempFile("meta", ".gcode")
        Slicer(printer, BuiltinProfiles.filaments.first(), process).slice(listOf(mesh), out) { _, _ -> }
        val text = out.readText()
        if (dir == null) out.delete()
        return text
    }

    @Test
    fun moonrakerCanReadIt() {
        val g = sliceSample()
        val id = Regex("; generated by (.+?) on \\d{4}-\\d{2}-\\d{2} at \\d{2}:\\d{2}:\\d{2}").find(g)
        assertNotNull(id, "slicer identification line")
        assertTrue(id.groupValues[1].startsWith("OrcaPhone "))
        // Fallback used by older Moonraker versions: a known slicer name followed by "<version> on".
        assertNotNull(Regex("(PrusaSlicer|SuperSlicer|OrcaSlicer)\\s(.*)\\son").find(g.take(1 shl 20)))
        val footer = g.takeLast(1 shl 20)
        val time = Regex(";\\sestimated\\sprinting\\stime.*").find(footer)?.value
        assertNotNull(time)
        assertTrue(Regex("\\d+[hms]").containsMatchIn(time), time)
        assertNotNull(Regex("total\\sfilament\\sused\\s\\[g\\]\\s=\\s(\\d+\\.?\\d*)").find(footer))
        assertNotNull(Regex("filament\\sused\\s\\[mm\\]\\s=\\s(\\S+)\\n").find(footer))
        assertNotNull(Regex("; first_layer_temperature = (\\d+)").find(footer))
        assertNotNull(Regex("; layer_height = (\\d+\\.?\\d*)").find(footer))
        // OrcaSlicer 2.5.2: first layer time is the first layer only, so less than the whole print
        val first = Regex("; estimated first layer printing time \\(normal mode\\) = (.+)").find(g)
        assertNotNull(first)
        assertTrue(first.groupValues[1] != time.substringAfter("= "), "first layer time equals total time")

        val thumbs = Regex("(thumbnail(?:_[A-Za-z0-9]+)?) begin([;/+=\\w\\s]+?); \\1 end").findAll(g).toList()
        assertEquals(2, thumbs.size)
        for (m in thumbs) {
            val lines = m.groupValues[2].replace("; ", "").split(Regex("\\r?\\n"))
            val info = Regex("\\d+").findAll(lines[0]).map { it.value.toInt() }.toList()
            val data = lines.subList(1, lines.size - 1).joinToString("")
            assertEquals(3, info.size)
            assertEquals(info[2], data.length, "declared base64 length")
            val img = assertNotNull(ImageIO.read(ByteArrayInputStream(Base64.getDecoder().decode(data))))
            assertEquals(info[0], img.width); assertEquals(info[1], img.height)
            // The model is drawn (opaque pixels in the middle) on a transparent background (corners).
            assertTrue((img.getRGB(img.width / 2, img.height / 2) ushr 24) > 200, "centre pixel opaque")
            assertEquals(0, img.getRGB(0, 0) ushr 24, "corner transparent")
        }
    }

    @Test
    fun chamberPlaceholdersFromOrcaSlicerStartGcode() {
        // OrcaSlicer 2.4.1 start macros can pass chamber_minimal_temperature; OrcaPhone fills in 0 (no chamber control).
        val printer = BuiltinProfiles.printers.first().copy(startGcode = "PRINT_START CHAMBER=[chamber_temperature] CHAMBER_MIN={chamber_minimal_temperature}")
        val process = BuiltinProfiles.processes.first { it.id == "builtin-0.20" }
        val mesh = Primitives.box(10.0, 10.0, 2.0).transformed(Mat4.translation(printer.bedWidth / 2, printer.bedDepth / 2, 1.0))
        val out = File.createTempFile("chamber", ".gcode")
        Slicer(printer, BuiltinProfiles.filaments.first(), process).slice(listOf(mesh), out) { _, _ -> }
        val g = out.readText(); out.delete()
        assertTrue(g.contains("PRINT_START CHAMBER=0 CHAMBER_MIN=0"), "placeholders not filled")
    }

    @Test
    fun emptyThumbnailIsTransparent() {
        val png = Thumbnail.renderPng(emptyList(), 16, 16, 0xff0000)
        val img = ImageIO.read(ByteArrayInputStream(png))
        assertEquals(16, img.width)
        assertEquals(0, img.getRGB(8, 8) ushr 24)
    }
}
